CREATE DATABASE  IF NOT EXISTS `vacations_project`;
USE `vacations_project`;


DROP TABLE IF EXISTS `followers`;
CREATE TABLE `followers` (
  `userId` int NOT NULL,
  `vacationId` int NOT NULL,
  KEY `fk_vacations_project_user_idx` (`userId`),
  KEY `k_vacations_project_vacation_idx` (`vacationId`),
  CONSTRAINT `fk_vacations_project_user` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `k_vacations_project_vacation` FOREIGN KEY (`vacationId`) REFERENCES `vacations` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

LOCK TABLES `followers` WRITE;
